/**
 * The message catalogs bundled into main and both renderers (LOCALIZATION_PLAN D1).
 *
 * Every namespace file is imported explicitly: `src/common` is compiled by two TypeScript projects
 * and bundled by three Vite builds, and a plain `import` is the one form all of them agree on.
 * `scripts/i18n-check.cjs` fails when a namespace file exists on disk but is missing here.
 *
 * Translations are not imported here: `translations.generated.ts` imports every `<lang>/<ns>.json`
 * and is regenerated by `npm run i18n:keys` (and `i18n:merge`), so adding a language needs no
 * TypeScript edit (D12).
 */
import { mergeNamespaces, type Catalog } from "./catalogs-core";
import enCommands from "./locales/en/commands.json";
import enCommon from "./locales/en/common.json";
import enDialogs from "./locales/en/dialogs.json";
import enEmu from "./locales/en/emu.json";
import enMenu from "./locales/en/menu.json";
import enMessages from "./locales/en/messages.json";
import enPanels from "./locales/en/panels.json";
import enSettings from "./locales/en/settings.json";
import enStatusbar from "./locales/en/statusbar.json";
import enToolbar from "./locales/en/toolbar.json";

/** The English namespace files, keyed by namespace name. */
export const SOURCE_NAMESPACES: Readonly<Record<string, Record<string, unknown>>> = {
  commands: enCommands,
  common: enCommon,
  dialogs: enDialogs,
  emu: enEmu,
  menu: enMenu,
  messages: enMessages,
  panels: enPanels,
  settings: enSettings,
  statusbar: enStatusbar,
  toolbar: enToolbar
};

/** English, merged. */
export const SOURCE_CATALOG: Catalog = mergeNamespaces(SOURCE_NAMESPACES);
